package com.bank.onbord.service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Produces a valid completion order via Kahn's algorithm.
public class OnboardingOrderService {
    private static final Logger log = Logger.getLogger(OnboardingOrderService.class.getName());

    public List<Integer> completionOrder(int taskCount, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < taskCount; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[taskCount];
        for (int[] p : prerequisites) {             // p = {prerequisite, dependent}
            adj.get(p[0]).add(p[1]);
            indeg[p[1]]++;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < taskCount; i++)
            if (indeg[i] == 0) queue.add(i);
        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int t = queue.poll();
            order.add(t);                           // record the actual order
            for (int next : adj.get(t))
                if (--indeg[next] == 0) queue.add(next);
        }
        if (order.size() != taskCount) {
            log.severe("Cycle detected: returning empty order");
            return new ArrayList<>();
        }
        log.info(() -> "Onboarding completion order = " + order);
        return order;
    }
}
